import React, {
  useEffect,
  useRef,
  useState,
} from 'react';

import { toast } from 'react-toastify';

import {
  FiPlus,
  FiEdit2,
  FiTrash2,
  FiStar,
  FiImage,
  FiMessageSquare,
  FiUser,
  FiCheckCircle,
  FiGlobe,
} from 'react-icons/fi';

import api from '../../services/api';
import { getImageUrl } from '../../utils/helpers';

import AdminTable from '../common/AdminTable';
import AdminModal from '../common/AdminModal';
import AdminCard from '../common/AdminCard';

import {
  useLanguage,
} from '../../contexts/LanguageContext';


const DEFAULT_AVATAR =
  '/default-avatar.png';


// ==========================================
// INITIAL FORM
// ==========================================

const initialForm = {
  name_en: '',
  name_km: '',

  role_en: '',
  role_km: '',

  content_en: '',
  content_km: '',

  rating: 5,
  is_active: true,
  order: 0,
};


// ==========================================
// ADMIN TESTIMONIALS
// ==========================================

const AdminTestimonials = () => {

  // ========================================
  // LANGUAGE
  // ========================================

  const {
    t,
    language,
  } = useLanguage();


  const isKhmer =
    language === 'km' ||
    language === 'kh';


  // ========================================
  // TRANSLATION FALLBACK
  // ========================================

  const tr = (
    key,
    englishFallback,
    khmerFallback
  ) => {

    const translated =
      t(key);


    if (
      translated &&
      translated !== key
    ) {
      return translated;
    }


    return isKhmer
      ? khmerFallback
      : englishFallback;
  };


  // ========================================
  // CURRENT LANGUAGE FIELDS
  // ========================================

  const nameField =
    isKhmer
      ? 'name_km'
      : 'name_en';


  const roleField =
    isKhmer
      ? 'role_km'
      : 'role_en';


  const contentField =
    isKhmer
      ? 'content_km'
      : 'content_en';


  // ========================================
  // STATES
  // ========================================

  const [
    testimonials,
    setTestimonials,
  ] = useState([]);


  const [
    loading,
    setLoading,
  ] = useState(true);


  const [
    modalOpen,
    setModalOpen,
  ] = useState(false);


  const [
    editingTestimonial,
    setEditingTestimonial,
  ] = useState(null);


  const [
    formData,
    setFormData,
  ] = useState({
    ...initialForm,
  });


  const [
    avatarFile,
    setAvatarFile,
  ] = useState(null);


  const [
    avatarPreview,
    setAvatarPreview,
  ] = useState(null);


  const [
    submitting,
    setSubmitting,
  ] = useState(false);


  const fileInputRef =
    useRef(null);


  // ========================================
  // GET DISPLAY NAME
  // ========================================

  const getTestimonialName = (
    testimonial
  ) => {

    if (!testimonial) {
      return '-';
    }


    if (isKhmer) {

      return (
        testimonial.name_km ||
        testimonial.name_en ||
        testimonial.name ||
        '-'
      );
    }


    return (
      testimonial.name_en ||
      testimonial.name_km ||
      testimonial.name ||
      '-'
    );
  };


  // ========================================
  // GET DISPLAY ROLE
  // ========================================

  const getTestimonialRole = (
    testimonial
  ) => {

    if (!testimonial) {
      return '-';
    }


    if (isKhmer) {

      return (
        testimonial.role_km ||
        testimonial.role_en ||
        testimonial.role ||
        '-'
      );
    }


    return (
      testimonial.role_en ||
      testimonial.role_km ||
      testimonial.role ||
      '-'
    );
  };


  // ========================================
  // GET DISPLAY CONTENT
  // ========================================

  const getTestimonialContent = (
    testimonial
  ) => {

    if (!testimonial) {
      return '-';
    }


    if (isKhmer) {

      return (
        testimonial.content_km ||
        testimonial.content_en ||
        testimonial.content ||
        '-'
      );
    }


    return (
      testimonial.content_en ||
      testimonial.content_km ||
      testimonial.content ||
      '-'
    );
  };


  // ========================================
  // LOAD TESTIMONIALS
  // ========================================

  useEffect(() => {

    fetchTestimonials();

    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);


  // ========================================
  // CLEAN PREVIEW
  // ========================================

  useEffect(() => {

    return () => {

      if (
        avatarPreview &&
        avatarPreview.startsWith(
          'blob:'
        )
      ) {

        URL.revokeObjectURL(
          avatarPreview
        );
      }
    };

  }, [avatarPreview]);


  // ========================================
  // FETCH TESTIMONIALS
  // ========================================

  const fetchTestimonials =
    async () => {

      try {

        setLoading(true);


        const response =
          await api.get(
            '/api/testimonials/'
          );


        setTestimonials(
          Array.isArray(
            response.data
          )
            ? response.data
            : []
        );

      } catch (error) {

        console.error(
          'Fetch testimonials error:',
          error
        );


        toast.error(
          error.response?.data?.detail ||
          tr(
            'testimonials.loadFailed',
            'Failed to load testimonials.',
            'មិនអាចទាញយកមតិយោបល់បានទេ។'
          )
        );

      } finally {

        setLoading(false);
      }
    };


  // ========================================
  // RESET FORM
  // ========================================

  const resetForm = () => {

    setEditingTestimonial(
      null
    );


    setFormData({
      ...initialForm,
    });


    setAvatarFile(null);


    if (
      avatarPreview &&
      avatarPreview.startsWith(
        'blob:'
      )
    ) {

      URL.revokeObjectURL(
        avatarPreview
      );
    }


    setAvatarPreview(null);


    if (
      fileInputRef.current
    ) {

      fileInputRef.current.value =
        '';
    }


    setSubmitting(false);
  };


  // ========================================
  // OPEN CREATE MODAL
  // ========================================

  const openCreateModal = () => {

    resetForm();

    setModalOpen(true);
  };


  // ========================================
  // CLOSE MODAL
  // ========================================

  const closeModal = () => {

    if (submitting) {
      return;
    }


    setModalOpen(false);

    resetForm();
  };


  // ========================================
  // HANDLE INPUT CHANGE
  // ========================================

  const handleInputChange = (
    event
  ) => {

    const {
      name,
      value,
      type,
      checked,
    } = event.target;


    setFormData(
      (previous) => ({

        ...previous,

        [name]:
          type === 'checkbox'
            ? checked
            : value,
      })
    );
  };


  // ========================================
  // AVATAR CHANGE
  // ========================================

  const handleAvatarChange = (
    event
  ) => {

    const file =
      event.target.files?.[0];


    if (!file) {
      return;
    }


    const allowedTypes = [
      'image/jpeg',
      'image/jpg',
      'image/png',
      'image/webp',
    ];


    if (
      !allowedTypes.includes(
        file.type
      )
    ) {

      toast.error(
        tr(
          'testimonials.invalidImage',
          'Please select a JPG, JPEG, PNG or WEBP image.',
          'សូមជ្រើសរើសរូបភាពប្រភេទ JPG, JPEG, PNG ឬ WEBP។'
        )
      );


      event.target.value = '';

      return;
    }


    const maxSize =
      5 * 1024 * 1024;


    if (
      file.size > maxSize
    ) {

      toast.error(
        tr(
          'testimonials.imageTooLarge',
          'Image must be 5 MB or smaller.',
          'រូបភាពត្រូវមានទំហំ 5 MB ឬតូចជាងនេះ។'
        )
      );


      event.target.value = '';

      return;
    }


    if (
      avatarPreview &&
      avatarPreview.startsWith(
        'blob:'
      )
    ) {

      URL.revokeObjectURL(
        avatarPreview
      );
    }


    setAvatarFile(file);


    setAvatarPreview(
      URL.createObjectURL(
        file
      )
    );
  };


  // ========================================
  // EDIT TESTIMONIAL
  // ========================================

  const handleEdit = (
    testimonial
  ) => {

    setEditingTestimonial(
      testimonial
    );


    setFormData({

      name_en:
        testimonial.name_en ||
        testimonial.name ||
        '',


      name_km:
        testimonial.name_km ||
        '',


      role_en:
        testimonial.role_en ||
        testimonial.role ||
        '',


      role_km:
        testimonial.role_km ||
        '',


      content_en:
        testimonial.content_en ||
        testimonial.content ||
        '',


      content_km:
        testimonial.content_km ||
        '',


      rating:
        Number(
          testimonial.rating
        ) || 5,


      is_active:
        testimonial.is_active ??
        true,


      order:
        Number(
          testimonial.order
        ) || 0,
    });


    setAvatarFile(null);


    if (
      avatarPreview &&
      avatarPreview.startsWith(
        'blob:'
      )
    ) {

      URL.revokeObjectURL(
        avatarPreview
      );
    }


    setAvatarPreview(null);


    if (
      fileInputRef.current
    ) {

      fileInputRef.current.value =
        '';
    }


    setModalOpen(true);
  };


  // ========================================
  // SUBMIT
  // ========================================

  const handleSubmit = async (
    event
  ) => {

    event.preventDefault();


    // ======================================
    // VALIDATE CURRENT LANGUAGE NAME
    // ======================================

    if (
      !String(
        formData[nameField] || ''
      ).trim()
    ) {

      toast.error(
        isKhmer
          ? 'សូមបញ្ចូលឈ្មោះ។'
          : 'Please enter the name.'
      );

      return;
    }


    // ======================================
    // VALIDATE CURRENT LANGUAGE CONTENT
    // ======================================

    if (
      !String(
        formData[contentField] ||
        ''
      ).trim()
    ) {

      toast.error(
        isKhmer
          ? 'សូមបញ្ចូលមតិយោបល់។'
          : 'Please enter the testimonial content.'
      );

      return;
    }


    try {

      setSubmitting(true);


      const data =
        new FormData();


      // ====================================
      // ENGLISH CONTENT
      // ====================================

      data.append(
        'name_en',
        formData.name_en.trim()
      );


      data.append(
        'role_en',
        formData.role_en.trim()
      );


      data.append(
        'content_en',
        formData.content_en.trim()
      );


      // ====================================
      // KHMER CONTENT
      // ====================================

      data.append(
        'name_km',
        formData.name_km.trim()
      );


      data.append(
        'role_km',
        formData.role_km.trim()
      );


      data.append(
        'content_km',
        formData.content_km.trim()
      );


      // ====================================
      // COMMON DATA
      // ====================================

      data.append(
        'rating',
        String(
          Number(
            formData.rating
          ) || 5
        )
      );


      data.append(
        'is_active',
        String(
          formData.is_active
        )
      );


      data.append(
        'order',
        String(
          Number(
            formData.order
          ) || 0
        )
      );


      // ====================================
      // AVATAR
      // ====================================

      if (avatarFile) {

        data.append(
          'avatar',
          avatarFile
        );
      }


      // ====================================
      // UPDATE
      // ====================================

      if (
        editingTestimonial
      ) {

        await api.put(
          `/api/testimonials/${editingTestimonial.id}`,
          data,
          {
            headers: {
              'Content-Type':
                'multipart/form-data',
            },
          }
        );


        toast.success(
          tr(
            'testimonials.updatedSuccess',
            'Testimonial updated successfully.',
            'បានកែប្រែមតិយោបល់ដោយជោគជ័យ។'
          )
        );

      } else {

        // ==================================
        // CREATE
        // ==================================

        await api.post(
          '/api/testimonials/',
          data,
          {
            headers: {
              'Content-Type':
                'multipart/form-data',
            },
          }
        );


        toast.success(
          tr(
            'testimonials.createdSuccess',
            'Testimonial created successfully.',
            'បានបង្កើតមតិយោបល់ដោយជោគជ័យ។'
          )
        );
      }


      setModalOpen(false);

      resetForm();


      await fetchTestimonials();

    } catch (error) {

      console.error(
        'Testimonial submit error:',
        error
      );


      const detail =
        error.response?.data
          ?.detail ||
        error.response?.data
          ?.message;


      if (
        Array.isArray(detail)
      ) {

        toast.error(
          detail
            .map(
              (item) =>
                item?.msg ||
                tr(
                  'testimonials.operationFailed',
                  'Operation failed.',
                  'ប្រតិបត្តិការមិនបានជោគជ័យ។'
                )
            )
            .join(', ')
        );

      } else {

        toast.error(
          detail ||
          tr(
            'testimonials.operationFailed',
            'Operation failed.',
            'ប្រតិបត្តិការមិនបានជោគជ័យ។'
          )
        );
      }

    } finally {

      setSubmitting(false);
    }
  };


  // ========================================
  // DELETE
  // ========================================

  const handleDelete = async (
    id
  ) => {

    const confirmDelete =
      window.confirm(
        tr(
          'testimonials.deleteConfirm',
          'Are you sure you want to delete this testimonial?',
          'តើអ្នកប្រាកដថាចង់លុបមតិយោបល់នេះមែនទេ?'
        )
      );


    if (!confirmDelete) {
      return;
    }


    try {

      await api.delete(
        `/api/testimonials/${id}`
      );


      toast.success(
        tr(
          'testimonials.deletedSuccess',
          'Testimonial deleted successfully.',
          'បានលុបមតិយោបល់ដោយជោគជ័យ។'
        )
      );


      await fetchTestimonials();

    } catch (error) {

      console.error(
        'Delete testimonial error:',
        error
      );


      toast.error(
        error.response?.data
          ?.detail ||
        tr(
          'testimonials.deleteFailed',
          'Failed to delete testimonial.',
          'មិនអាចលុបមតិយោបល់បានទេ។'
        )
      );
    }
  };


  // ========================================
  // RENDER STARS
  // ========================================

  const renderStars = (
    rating
  ) => {

    const safeRating =
      Math.max(
        0,
        Math.min(
          5,
          Number(rating) || 0
        )
      );


    return (

      <div
        className="
          flex
          items-center
          gap-1
        "
      >

        {
          [...Array(5)].map(
            (_, index) => (

              <FiStar
                key={index}

                size={16}

                className={
                  index <
                  safeRating
                    ? 'text-red-600 fill-current'
                    : 'text-blue-300'
                }
              />

            )
          )
        }

      </div>
    );
  };


  // ========================================
  // TABLE COLUMNS
  // ========================================

  const columns = [

    // ======================================
    // AVATAR
    // ======================================

    {
      key: 'avatar',

      label:
        tr(
          'testimonials.avatar',
          'Avatar',
          'រូបភាព'
        ),

      render: (value) => (

        <div
          className="
            w-14
            h-14

            rounded-xl

            overflow-hidden

            border
            border-blue-200

            bg-blue-50

            shadow-sm
          "
        >

          <img
            src={
              getImageUrl(
                value,
                DEFAULT_AVATAR
              )
            }

            alt={
              tr(
                'testimonials.avatar',
                'Avatar',
                'រូបភាព'
              )
            }

            className="
              w-full
              h-full

              object-cover
            "

            onError={(event) => {

              event.currentTarget.src =
                DEFAULT_AVATAR;
            }}
          />

        </div>
      ),
    },


    // ======================================
    // NAME
    // ======================================

    {
      key: 'name_en',

      label:
        tr(
          'testimonials.name',
          'Name',
          'ឈ្មោះ'
        ),

      render: (
        value,
        row
      ) => (

        <div
          className="
            flex
            items-center
            gap-3
          "
        >

          <div
            className="
              w-9
              h-9

              flex
              items-center
              justify-center

              rounded-lg

              bg-blue-50
              text-blue-900

              flex-shrink-0
            "
          >

            <FiUser
              size={17}
            />

          </div>


          <p
            className="
              font-semibold
              text-blue-900
            "
          >
            {
              getTestimonialName(
                row
              )
            }
          </p>

        </div>
      ),
    },


    // ======================================
    // ROLE
    // ======================================

    {
      key: 'role_en',

      label:
        tr(
          'testimonials.role',
          'Role',
          'តួនាទី'
        ),

      render: (
        value,
        row
      ) => (

        <span
          className="
            inline-flex

            px-3
            py-1.5

            rounded-full

            bg-blue-50
            text-blue-900

            border
            border-blue-200

            text-xs
            font-medium
          "
        >
          {
            getTestimonialRole(
              row
            )
          }
        </span>
      ),
    },


    // ======================================
    // CONTENT
    // ======================================

    {
      key: 'content_en',

      label:
        tr(
          'testimonials.content',
          'Testimonial',
          'មតិយោបល់'
        ),

      render: (
        value,
        row
      ) => (

        <p
          className="
            max-w-xs

            text-sm
            text-blue-500

            line-clamp-2

            leading-5
          "
        >
          {
            getTestimonialContent(
              row
            )
          }
        </p>
      ),
    },


    // ======================================
    // RATING
    // ======================================

    {
      key: 'rating',

      label:
        tr(
          'testimonials.rating',
          'Rating',
          'ការវាយតម្លៃ'
        ),

      render: (value) => (

        <div
          className="
            space-y-1
          "
        >

          {
            renderStars(
              value
            )
          }


          <span
            className="
              text-xs
              text-blue-300
            "
          >
            {value || 0}/5
          </span>

        </div>
      ),
    },


    // ======================================
    // STATUS
    // ======================================

    {
      key: 'is_active',

      label:
        tr(
          'common.status',
          'Status',
          'ស្ថានភាព'
        ),

      render: (value) => (

        <span
          className={`
            inline-flex
            items-center
            gap-2

            px-3
            py-1.5

            rounded-full

            text-xs
            font-semibold

            border

            ${
              value
                ? 'bg-blue-50 text-blue-700 border-blue-200'
                : 'bg-red-50 text-red-600 border-red-200'
            }
          `}
        >

          <span
            className={`
              w-2
              h-2

              rounded-full

              ${
                value
                  ? 'bg-blue-500'
                  : 'bg-red-500'
              }
            `}
          />


          {
            value
              ? tr(
                  'common.active',
                  'Active',
                  'សកម្ម'
                )
              : tr(
                  'common.inactive',
                  'Inactive',
                  'អសកម្ម'
                )
          }

        </span>
      ),
    },


    // ======================================
    // ACTIONS
    // ======================================

    {
      key: 'actions',

      label:
        tr(
          'common.actions',
          'Actions',
          'សកម្មភាព'
        ),

      render: (
        _,
        row
      ) => (

        <div
          className="
            flex
            items-center
            gap-2
          "
        >

          <button
            type="button"

            onClick={() =>
              handleEdit(
                row
              )
            }

            title={
              tr(
                'testimonials.editTestimonial',
                'Edit Testimonial',
                'កែប្រែមតិយោបល់'
              )
            }

            className="
              w-9
              h-9

              flex
              items-center
              justify-center

              rounded-lg

              bg-blue-50
              text-blue-900

              hover:bg-blue-900
              hover:text-white

              transition-all
              duration-200
            "
          >

            <FiEdit2
              size={16}
            />

          </button>


          <button
            type="button"

            onClick={() =>
              handleDelete(
                row.id
              )
            }

            title={
              tr(
                'testimonials.deleteTestimonial',
                'Delete Testimonial',
                'លុបមតិយោបល់'
              )
            }

            className="
              w-9
              h-9

              flex
              items-center
              justify-center

              rounded-lg

              bg-red-50
              text-red-600

              hover:bg-red-600
              hover:text-white

              transition-all
              duration-200
            "
          >

            <FiTrash2
              size={16}
            />

          </button>

        </div>
      ),
    },
  ];


  // ========================================
  // RETURN
  // ========================================

  return (

    <div
      className={`
        w-full

        ${
          isKhmer
            ? 'font-khmer'
            : 'font-english'
        }
      `}
    >

      {/* ==================================
          HEADER
      ================================== */}

      <div
        className="
          flex
          flex-col

          sm:flex-row
          sm:items-center
          sm:justify-between

          gap-4

          mb-7
        "
      >

        <div
          className="
            flex
            items-center
            gap-3
          "
        >

          <div
            className="
              w-12
              h-12

              flex
              items-center
              justify-center

              rounded-xl

              bg-blue-900
              text-white

              shadow-sm
            "
          >

            <FiMessageSquare
              size={22}
            />

          </div>


          <div>

            <h1
              className="
                text-2xl
                md:text-3xl

                font-bold

                text-blue-900

                leading-tight
              "
            >
              {
                tr(
                  'testimonials.title',
                  'Testimonials',
                  'មតិយោបល់'
                )
              }
            </h1>


            <p
              className="
                text-sm
                text-blue-400

                mt-1
              "
            >
              {
                tr(
                  'testimonials.subtitle',
                  'Manage student testimonials and feedback',
                  'គ្រប់គ្រងមតិយោបល់ និងការវាយតម្លៃ'
                )
              }
            </p>

          </div>

        </div>


        <button
          type="button"

          onClick={
            openCreateModal
          }

          className="
            inline-flex
            items-center
            justify-center
            gap-2

            h-11

            px-5

            bg-red-600
            hover:bg-red-700

            text-white

            rounded-xl

            text-sm
            font-semibold

            shadow-sm
            hover:shadow-md

            transition-all
            duration-200
          "
        >

          <FiPlus
            size={18}
          />


          {
            tr(
              'testimonials.addTestimonial',
              'Add Testimonial',
              'បន្ថែមមតិយោបល់'
            )
          }

        </button>

      </div>


      {/* ==================================
          TABLE
      ================================== */}

      <AdminCard
        className="
          overflow-hidden

          bg-white

          border
          border-blue-200

          rounded-2xl

          shadow-sm
        "
      >

        <AdminTable
          columns={columns}

          data={
            testimonials
          }

          loading={
            loading
          }
        />

      </AdminCard>


      {/* ==================================
          MODAL
      ================================== */}

      <AdminModal
        isOpen={
          modalOpen
        }

        onClose={
          closeModal
        }

        title={
          editingTestimonial
            ? tr(
                'testimonials.editTestimonial',
                'Edit Testimonial',
                'កែប្រែមតិយោបល់'
              )
            : tr(
                'testimonials.createTestimonial',
                'Create Testimonial',
                'បង្កើតមតិយោបល់'
              )
        }
      >

        <div
          className={
            isKhmer
              ? 'font-khmer'
              : 'font-english'
          }
        >

          <form
            onSubmit={
              handleSubmit
            }
          >

            <div
              className="
                space-y-6
              "
            >

              {/* ============================
                  LANGUAGE CONTENT
              ============================ */}

              <div
                className="
                  border
                  border-blue-200

                  rounded-2xl

                  overflow-hidden
                "
              >

                {/* LANGUAGE HEADER */}

                <div
                  className="
                    flex
                    items-center
                    justify-between

                    gap-3

                    px-4
                    py-3

                    bg-blue-50

                    border-b
                    border-blue-200
                  "
                >

                  <div
                    className="
                      flex
                      items-center
                      gap-2
                    "
                  >

                    <FiGlobe
                      className="
                        text-blue-900
                      "
                    />


                    <h3
                      className="
                        font-semibold
                        text-blue-900
                      "
                    >
                      {
                        tr(
                          'testimonials.contentSection',
                          'Testimonial Content',
                          'មាតិកាមតិយោបល់'
                        )
                      }
                    </h3>

                  </div>


                  <span
                    className="
                      inline-flex
                      items-center

                      px-3
                      py-1.5

                      rounded-full

                      bg-white

                      border
                      border-blue-200

                      text-xs
                      font-semibold

                      text-blue-900
                    "
                  >
                    {
                      isKhmer
                        ? 'ខ្មែរ'
                        : 'English'
                    }
                  </span>

                </div>


                {/* LANGUAGE FORM */}

                <div
                  className="
                    p-4

                    space-y-5
                  "
                >

                  {/* NAME */}

                  <div>

                    <label
                      className="
                        block

                        text-sm
                        font-semibold

                        text-blue-900

                        mb-1.5
                      "
                    >

                      {
                        tr(
                          'testimonials.name',
                          'Name',
                          'ឈ្មោះ'
                        )
                      }


                      <span
                        className="
                          text-red-600
                          ml-1
                        "
                      >
                        *
                      </span>

                    </label>


                    <input
                      type="text"

                      name={
                        nameField
                      }

                      value={
                        formData[
                          nameField
                        ]
                      }

                      onChange={
                        handleInputChange
                      }

                      placeholder={
                        tr(
                          'testimonials.namePlaceholder',
                          'Enter name',
                          'បញ្ចូលឈ្មោះ'
                        )
                      }

                      required

                      className={`
                        w-full

                        px-4
                        py-2.5

                        border
                        border-blue-200

                        rounded-xl

                        bg-white

                        text-blue-900

                        placeholder:text-blue-300

                        focus:outline-none
                        focus:ring-2
                        focus:ring-blue-900/20
                        focus:border-blue-900

                        transition-all
                        duration-200

                        ${
                          isKhmer
                            ? 'font-khmer'
                            : 'font-english'
                        }
                      `}
                    />

                  </div>


                  {/* ROLE */}

                  <div>

                    <label
                      className="
                        block

                        text-sm
                        font-semibold

                        text-blue-900

                        mb-1.5
                      "
                    >
                      {
                        tr(
                          'testimonials.role',
                          'Role',
                          'តួនាទី'
                        )
                      }
                    </label>


                    <input
                      type="text"

                      name={
                        roleField
                      }

                      value={
                        formData[
                          roleField
                        ]
                      }

                      onChange={
                        handleInputChange
                      }

                      placeholder={
                        tr(
                          'testimonials.rolePlaceholder',
                          'Example: Student',
                          'ឧទាហរណ៍៖ សិស្ស'
                        )
                      }

                      className={`
                        w-full

                        px-4
                        py-2.5

                        border
                        border-blue-200

                        rounded-xl

                        bg-white

                        text-blue-900

                        placeholder:text-blue-300

                        focus:outline-none
                        focus:ring-2
                        focus:ring-blue-900/20
                        focus:border-blue-900

                        transition-all
                        duration-200

                        ${
                          isKhmer
                            ? 'font-khmer'
                            : 'font-english'
                        }
                      `}
                    />

                  </div>


                  {/* CONTENT */}

                  <div>

                    <label
                      className="
                        block

                        text-sm
                        font-semibold

                        text-blue-900

                        mb-1.5
                      "
                    >

                      {
                        tr(
                          'testimonials.content',
                          'Testimonial',
                          'មតិយោបល់'
                        )
                      }


                      <span
                        className="
                          text-red-600
                          ml-1
                        "
                      >
                        *
                      </span>

                    </label>


                    <textarea
                      name={
                        contentField
                      }

                      value={
                        formData[
                          contentField
                        ]
                      }

                      onChange={
                        handleInputChange
                      }

                      rows={5}

                      required

                      placeholder={
                        tr(
                          'testimonials.contentPlaceholder',
                          'Enter testimonial content',
                          'បញ្ចូលមតិយោបល់'
                        )
                      }

                      className={`
                        w-full

                        px-4
                        py-3

                        border
                        border-blue-200

                        rounded-xl

                        bg-white

                        text-blue-900

                        placeholder:text-blue-300

                        resize-y

                        focus:outline-none
                        focus:ring-2
                        focus:ring-blue-900/20
                        focus:border-blue-900

                        transition-all
                        duration-200

                        ${
                          isKhmer
                            ? 'font-khmer'
                            : 'font-english'
                        }
                      `}
                    />

                  </div>

                </div>

              </div>


              {/* ============================
                  GENERAL INFORMATION
              ============================ */}

              <div
                className="
                  border
                  border-blue-200

                  rounded-2xl

                  overflow-hidden
                "
              >

                <div
                  className="
                    px-4
                    py-3

                    bg-blue-50

                    border-b
                    border-blue-200
                  "
                >

                  <h3
                    className="
                      font-semibold
                      text-blue-900
                    "
                  >
                    {
                      tr(
                        'common.generalInformation',
                        'General Information',
                        'ព័ត៌មានទូទៅ'
                      )
                    }
                  </h3>

                </div>


                <div
                  className="
                    p-4

                    space-y-5
                  "
                >

                  {/* RATING + ORDER */}

                  <div
                    className="
                      grid
                      grid-cols-1

                      md:grid-cols-2

                      gap-4
                    "
                  >

                    {/* RATING */}

                    <div>

                      <label
                        className="
                          block

                          text-sm
                          font-semibold

                          text-blue-900

                          mb-1.5
                        "
                      >
                        {
                          tr(
                            'testimonials.rating',
                            'Rating',
                            'ការវាយតម្លៃ'
                          )
                        }
                      </label>


                      <select
                        name="rating"

                        value={
                          formData.rating
                        }

                        onChange={
                          handleInputChange
                        }

                        className="
                          w-full

                          px-4
                          py-2.5

                          border
                          border-blue-200

                          rounded-xl

                          bg-white

                          text-blue-900

                          focus:outline-none
                          focus:ring-2
                          focus:ring-blue-900/20
                          focus:border-blue-900

                          transition-all
                          duration-200
                        "
                      >

                        <option value={5}>
                          5 ★★★★★
                        </option>

                        <option value={4}>
                          4 ★★★★
                        </option>

                        <option value={3}>
                          3 ★★★
                        </option>

                        <option value={2}>
                          2 ★★
                        </option>

                        <option value={1}>
                          1 ★
                        </option>

                      </select>

                    </div>


                    {/* ORDER */}

                    <div>

                      <label
                        className="
                          block

                          text-sm
                          font-semibold

                          text-blue-900

                          mb-1.5
                        "
                      >
                        {
                          tr(
                            'testimonials.order',
                            'Display Order',
                            'លំដាប់បង្ហាញ'
                          )
                        }
                      </label>


                      <input
                        type="number"

                        name="order"

                        min="0"

                        value={
                          formData.order
                        }

                        onChange={
                          handleInputChange
                        }

                        className="
                          w-full

                          px-4
                          py-2.5

                          border
                          border-blue-200

                          rounded-xl

                          bg-white

                          text-blue-900

                          focus:outline-none
                          focus:ring-2
                          focus:ring-blue-900/20
                          focus:border-blue-900

                          transition-all
                          duration-200
                        "
                      />

                    </div>

                  </div>


                  {/* ==========================
                      AVATAR
                  ========================== */}

                  <div>

                    <label
                      className="
                        block

                        text-sm
                        font-semibold

                        text-blue-900

                        mb-2
                      "
                    >
                      {
                        tr(
                          'testimonials.avatar',
                          'Avatar',
                          'រូបភាព'
                        )
                      }
                    </label>


                    <div
                      className="
                        flex
                        flex-col

                        sm:flex-row
                        sm:items-center

                        gap-4
                      "
                    >

                      {/* PREVIEW */}

                      <div
                        className="
                          w-24
                          h-24

                          rounded-2xl

                          overflow-hidden

                          bg-blue-50

                          border
                          border-blue-200

                          flex
                          items-center
                          justify-center

                          flex-shrink-0
                        "
                      >

                        {
                          avatarPreview ||
                          editingTestimonial
                            ?.avatar
                            ? (

                              <img
                                src={
                                  avatarPreview ||
                                  getImageUrl(
                                    editingTestimonial
                                      ?.avatar,
                                    DEFAULT_AVATAR
                                  )
                                }

                                alt={
                                  tr(
                                    'testimonials.avatar',
                                    'Avatar',
                                    'រូបភាព'
                                  )
                                }

                                className="
                                  w-full
                                  h-full

                                  object-cover
                                "

                                onError={
                                  (
                                    event
                                  ) => {

                                    event
                                      .currentTarget
                                      .src =
                                      DEFAULT_AVATAR;
                                  }
                                }
                              />

                            )
                            : (

                              <FiImage
                                size={30}

                                className="
                                  text-blue-300
                                "
                              />

                            )
                        }

                      </div>


                      {/* FILE INPUT */}

                      <div
                        className="
                          flex-1
                        "
                      >

                        <input
                          ref={
                            fileInputRef
                          }

                          type="file"

                          accept="
                            image/jpeg,
                            image/jpg,
                            image/png,
                            image/webp
                          "

                          onChange={
                            handleAvatarChange
                          }

                          className="
                            block
                            w-full

                            text-sm
                            text-blue-500

                            file:mr-4
                            file:py-2
                            file:px-4

                            file:rounded-lg
                            file:border-0

                            file:bg-blue-50
                            file:text-blue-900

                            file:font-semibold

                            hover:file:bg-blue-100

                            cursor-pointer
                          "
                        />


                        <p
                          className="
                            text-xs
                            text-blue-300

                            mt-2
                          "
                        >
                          {
                            tr(
                              'testimonials.imageHint',
                              'JPG, JPEG, PNG, WEBP — Maximum 5 MB',
                              'JPG, JPEG, PNG, WEBP — ទំហំអតិបរមា 5 MB'
                            )
                          }
                        </p>

                      </div>

                    </div>

                  </div>


                  {/* ==========================
                      STATUS
                  ========================== */}

                  <div
                    className="
                      flex
                      items-center
                      justify-between

                      gap-4

                      p-4

                      rounded-xl

                      bg-blue-50

                      border
                      border-blue-100
                    "
                  >

                    <div
                      className="
                        flex
                        items-center
                        gap-3
                      "
                    >

                      <div
                        className="
                          w-10
                          h-10

                          rounded-lg

                          bg-white

                          flex
                          items-center
                          justify-center

                          text-blue-900

                          border
                          border-blue-100
                        "
                      >

                        <FiCheckCircle
                          size={19}
                        />

                      </div>


                      <div>

                        <p
                          className="
                            text-sm
                            font-semibold
                            text-blue-900
                          "
                        >
                          {
                            tr(
                              'common.status',
                              'Status',
                              'ស្ថានភាព'
                            )
                          }
                        </p>


                        <p
                          className="
                            text-xs
                            text-blue-400

                            mt-0.5
                          "
                        >
                          {
                            formData.is_active
                              ? tr(
                                  'common.active',
                                  'Active',
                                  'សកម្ម'
                                )
                              : tr(
                                  'common.inactive',
                                  'Inactive',
                                  'អសកម្ម'
                                )
                          }
                        </p>

                      </div>

                    </div>


                    <button
                      type="button"

                      onClick={() =>
                        setFormData(
                          (
                            previous
                          ) => ({

                            ...previous,

                            is_active:
                              !previous.is_active,
                          })
                        )
                      }

                      className={`
                        relative

                        inline-flex

                        h-7
                        w-12

                        flex-shrink-0

                        cursor-pointer

                        rounded-full

                        transition-colors
                        duration-200

                        focus:outline-none

                        ${
                          formData.is_active
                            ? 'bg-blue-900'
                            : 'bg-blue-200'
                        }
                      `}
                    >

                      <span
                        className={`
                          pointer-events-none

                          inline-block

                          h-5
                          w-5

                          mt-1

                          rounded-full

                          bg-white

                          shadow

                          transform

                          transition-transform
                          duration-200

                          ${
                            formData.is_active
                              ? 'translate-x-6'
                              : 'translate-x-1'
                          }
                        `}
                      />

                    </button>

                  </div>

                </div>

              </div>

            </div>


            {/* ==================================
                ACTIONS
            ================================== */}

            <div
              className="
                flex
                flex-col-reverse

                sm:flex-row
                sm:justify-end

                gap-3

                mt-7
                pt-5

                border-t
                border-blue-100
              "
            >

              {/* CANCEL */}

              <button
                type="button"

                onClick={
                  closeModal
                }

                disabled={
                  submitting
                }

                className="
                  px-5
                  py-2.5

                  rounded-xl

                  border
                  border-blue-200

                  bg-white

                  text-blue-700

                  text-sm
                  font-semibold

                  hover:bg-blue-50

                  disabled:opacity-50
                  disabled:cursor-not-allowed

                  transition-all
                  duration-200
                "
              >
                {
                  tr(
                    'common.cancel',
                    'Cancel',
                    'បោះបង់'
                  )
                }
              </button>


              {/* SUBMIT */}

              <button
                type="submit"

                disabled={
                  submitting
                }

                className="
                  inline-flex
                  items-center
                  justify-center
                  gap-2

                  px-5
                  py-2.5

                  rounded-xl

                  bg-red-600
                  hover:bg-red-700

                  text-white

                  text-sm
                  font-semibold

                  shadow-sm

                  disabled:opacity-60
                  disabled:cursor-not-allowed

                  transition-all
                  duration-200
                "
              >

                {
                  submitting
                    ? (

                      <>

                        <span
                          className="
                            w-4
                            h-4

                            border-2
                            border-white/40
                            border-t-white

                            rounded-full

                            animate-spin
                          "
                        />


                        {
                          tr(
                            'common.saving',
                            'Saving...',
                            'កំពុងរក្សាទុក...'
                          )
                        }

                      </>

                    )
                    : editingTestimonial
                      ? (

                        <>

                          <FiEdit2
                            size={16}
                          />


                          {
                            tr(
                              'common.update',
                              'Update',
                              'កែប្រែ'
                            )
                          }

                        </>

                      )
                      : (

                        <>

                          <FiPlus
                            size={16}
                          />


                          {
                            tr(
                              'common.create',
                              'Create',
                              'បង្កើត'
                            )
                          }

                        </>

                      )
                }

              </button>

            </div>

          </form>

        </div>

      </AdminModal>

    </div>
  );
};


export default AdminTestimonials;
